from typing import List, Optional

class Solution:
    def levelOrderBottom(self, root: Optional[TreeNode]) -> List[List[int]]:
        def checkReverse(ans: List[List[int]]) -> List[List[int]]:
            l, r = 0, len(ans) - 1
            while l < r:
                ans[l], ans[r] = ans[r], ans[l]
                l += 1
                r -= 1
            return ans

        if not root:
            return []

        q = [root]
        ans = []
        while q:
            level_size = len(q)
            level_vals = []
            for _ in range(level_size):
                node = q.pop(0)
                level_vals.append(node.val)
                if node.left:
                    q.append(node.left)
                if node.right:
                    q.append(node.right)
            ans.append(level_vals)

        return checkReverse(ans)

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # Early exit: any character in s2 not present in s1 makes it impossible
        if not set(s2).issubset(set(s1)):
            return 0

        s2_len = len(s2)
        s2_idx = 0       # current position in s2
        s2_cnt = 0       # how many full s2 have been built
        cnt_s1 = 0       # how many s1 blocks have been processed
        first = {}       # map s2_idx -> (cnt_s1, s2_cnt) when first seen

        # Scan s1 blocks and detect a cycle
        while cnt_s1 < n1:
            cnt_s1 += 1
            for ch in s1:
                if ch == s2[s2_idx]:
                    s2_idx += 1
                    if s2_idx == s2_len:
                        s2_idx = 0
                        s2_cnt += 1
            # Cycle detection
            if s2_idx in first:
                pre_cnt_s1, pre_cnt_s2 = first[s2_idx]
                cycle_len = cnt_s1 - pre_cnt_s1
                cycle_s2 = s2_cnt - pre_cnt_s2
                remaining = n1 - pre_cnt_s1
                cycles = remaining // cycle_len
                s2_cnt += cycles * cycle_s2
                cnt_s1 += cycles * cycle_len
                # Finish the remaining blocks (if any) normally
                while cnt_s1 < n1:
                    cnt_s1 += 1
                    for ch in s1:
                        if ch == s2[s2_idx]:
                            s2_idx += 1
                            if s2_idx == s2_len:
                                s2_idx = 0
                                s2_cnt += 1
                break
            else:
                first[s2_idx] = (cnt_s1, s2_cnt)

        return s2_cnt // n2

