# Fixed implementation for bottom-up level order traversal
from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def levelOrderBottom(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []  # Return empty list instead of None

        q: List[TreeNode] = [root]
        ans: List[List[int]] = []

        while q:
            level: List[int] = []
            n = len(q)  # Correctly get current queue size
            for _ in range(n):
                node = q.pop(0)  # Dequeue front
                level.append(node.val)
                if node.left:
                    q.append(node.left)  # Properly enqueue left child
                if node.right:
                    q.append(node.right)  # Properly enqueue right child
            ans.append(level)

        # Reverse the levels to achieve bottom‑up order
        ans.reverse()
        return ans

