from typing import List
from collections import defaultdict

class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        if not pairs:
            return []
        graph = defaultdict(list)
        degree = defaultdict(int)
        for x, y in pairs:
            graph[x].append(y)
            degree[x] += 1
            degree[y] -= 1

        # Find start node: degree == 1, else any node with outgoing edges
        start = None
        for k, d in degree.items():
            if d == 1:
                start = k
                break
        if start is None:
            for k in graph:
                if graph[k]:
                    start = k
                    break
        if start is None:
            start = pairs[0][0]

        ans = []

        def dfs(u):
            while graph[u]:
                v = graph[u].pop()
                dfs(v)
            ans.append(u)

        dfs(start)
        ans.reverse()
        return [[ans[i], ans[i+1]] for i in range(len(ans)-1)]

