from typing import List
from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # Duplicate toppings to allow each up to two uses
        toppingCosts = toppingCosts * 2

        @cache
        def dfs(i: int, x: int) -> int:
            """Return sum of subsequence of toppingCosts[i:] closest to x."""
            if x < 0 or i == len(toppingCosts):
                return 0
            # option 1: skip this topping
            a = dfs(i + 1, x)
            # option 2: take this topping
            b = toppingCosts[i] + dfs(i + 1, x - toppingCosts[i])
            return min(a, b, key=lambda y: (abs(y - x), y))

        best = float('inf')
        for bc in baseCosts:
            cur = bc + dfs(0, target - bc)
            best = min(best, cur, key=lambda c: (abs(c - target), c))
        return best

