from typing import List
from functools import lru_cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # each topping can be used at most twice, duplicate to allow two uses
        toppingCosts = toppingCosts * 2

        @lru_cache(None)
        def dfs(i: int, remaining: int) -> int:
            # stop when out of toppings or remaining negative
            if i == len(toppingCosts) or remaining < 0:
                return 0
            skip = dfs(i + 1, remaining)
            take = toppingCosts[i] + dfs(i + 1, remaining - toppingCosts[i])
            # choose the result closest to the original remaining target
            return min(skip, take, key=lambda s: (abs(s - remaining), s))

