class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # If any character of s2 is missing from s1, impossible.
        if not set(s2).issubset(set(s1)):
            return 0
        # Keep only characters that appear in s2 for faster scanning.
        s1 = ''.join(ch for ch in s1 if ch in set(s2))

        # map from position in s1 after completing a s2 to (cnt1, cnt2)
        rec = {}
        cnt1 = cnt2 = 0
        index = 0  # position inside s1
        while cnt1 < n1:
            for ch in s2:
                pos = s1.find(ch, index)
                if pos == -1:
                    cnt1 += 1
                    index = s1.find(ch)
                else:
                    index = pos + 1
            cnt2 += 1
            if index not in rec:
                rec[index] = (cnt1, cnt2)
            else:
                pre_cnt1, pre_cnt2 = rec[index]
                cycle_len1 = cnt1 - pre_cnt1
                cycle_len2 = cnt2 - pre_cnt2
                remaining = n1 - pre_cnt1
                cycles = remaining // cycle_len1
                result = pre_cnt2 + cycles * cycle_len2
                return result // n2
        return cnt2 // n2

