from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.r, self.c = len(pizza), len(pizza[0])
        # Prefix sum of apples (0-index, inclusive)
        self.pref = [[0] * (self.c + 1) for _ in range(self.r + 1)]
        for i in range(self.r):
            row_sum = 0
            for j in range(self.c):
                if pizza[i][j] == 'A':
                    row_sum += 1
                self.pref[i+1][j+1] = self.pref[i][j+1] + row_sum

        @lru_cache(None)
        def dfs(i: int, j: int, cuts: int) -> int:
            # No apples → invalid piece
            if self._apples(i, j, self.r-1, self.c-1) == 0:
                return 0
            # No more cuts needed → one valid piece
            if cuts == 0:
                return 1
            total = 0
            # Horizontal cuts
            for r in range(i, self.r-1):
                if self._apples(i, j, r, self.c-1) > 0:
                    total += dfs(r+1, j, cuts-1)
            # Vertical cuts
            for c in range(j, self.c-1):
                if self._apples(i, j, self.r-1, c) > 0:
                    total += dfs(i, c+1, cuts-1)
            return total % (10**9+7)

        return dfs(0, 0, k-1) % (10**9+7)

    def _apples(self, r1: int, c1: int, r2: int, c2: int) -> int:
        # inclusive rectangle query using prefix sums
        return (
            self.pref[r2+1][c2+1]
            - self.pref[r1][c2+1]
            - self.pref[r2+1][c1]
            + self.pref[r1][c1]
        )

