        if i == n:
            return self.cost(prev, ct)
        key = (i, prev, ct, k)
        if key in self.memo:
            return self.memo[key]
        # Delete current character
        del_len = self.dp(i+1, prev, ct, k-1) if k > 0 else float('inf')
        # Keep current character
        if self.s[i] == prev:
            inc = self.dp(i+1, prev, ct+1, k)
        else:
            inc = self.cost(prev, ct) + self.dp(i+1, self.s[i], 1, k)
        res = min(inc, del_len)
        self.memo[key] = res
        return res

    def cost(self, ch, cnt):
        if cnt == 0:
            return 0
        if cnt == 1:
            return 1
        return 1 + len(str(cnt))

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        self.s = s
        self.memo = {}
        return self.dp(0, "", 0, k)

