class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # If any character needed by s2 is missing from s1, impossible.
        if not set(s2).issubset(set(s1)):
            return 0
        s1_len, s2_len = len(s1), len(s2)
        # Mapping from position in s2 to (number of s1 blocks processed, number of completed s2 strings)
        look = {}
        s2_pos = 0          # current index inside s2
        s1_used = 0         # how many s1 blocks have been processed
        s2_cnt = 0          # how many full s2 strings have been completed
        while s1_used < n1:
            # Scan through one copy of s1
            for ch in s1:
                if ch == s2[s2_pos]:
                    s2_pos += 1
                    if s2_pos == s2_len:
                        s2_pos = 0
                        s2_cnt += 1
            s1_used += 1
            # Record the state for cycle detection
            if s2_pos not in look:
                look[s2_pos] = (s1_used, s2_cnt)
            else:
                prev_s1, prev_s2 = look[s2_pos]
                # Length of the detected cycle (in s1 blocks and completed s2 strings)
                cycle_s1 = s1_used - prev_s1
                cycle_s2 = s2_cnt - prev_s2
                # How many full cycles we can still apply
                remaining = n1 - s1_used
                cycles = remaining // cycle_s1
                s2_cnt += cycles * cycle_s2
                s1_used += cycles * cycle_s1
                # Finish any leftover s1 blocks one by one
                while s1_used < n1:
                    for ch in s1:
                        if ch == s2[s2_pos]:
                            s2_pos += 1
                            if s2_pos == s2_len:
                                s2_pos = 0
                                s2_cnt += 1
                    s1_used += 1
                return s2_cnt // n2
        return s2_cnt // n2

