class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.r = len(pizza)
        self.c = len(pizza[0])
        MOD = 1000000007

        # Build 2D prefix sum
        self.pfsum = [[0] * self.c for _ in range(self.r)]
        for i in range(self.r):
            for j in range(self.c):
                self.pfsum[i][j] = 1 if pizza[i][j] == 'A' else 0
                if i > 0:
                    self.pfsum[i][j] += self.pfsum[i-1][j]
                if j > 0:
                    self.pfsum[i][j] += self.pfsum[i][j-1]
                if i > 0 and j > 0:
                    self.pfsum[i][j] -= self.pfsum[i-1][j-1]

        tot_apples = self.pfsum[self.r-1][self.c-1]
        if tot_apples < k:
            return 0

        return self.getWays(0,0,k) % MOD

    @cache
    def getWays(self, i, j, k):
        MOD = 1000000007
        if k == 1:
            # Check apples in the current piece
            total = self.pfsum[self.r-1][self.c-1]
            if i > 0:
                total -= self.pfsum[i-1][self.c-1]
            if j > 0:
                total -= self.pfsum[self.r-1][j-1]
            if i > 0 and j > 0:
                total += self.pfsum[i-1][j-1]
            return 1 if total > 0 else 0

        total = 0
        # Horizontal cuts
        for nr in range(i, self.r-1):
            top = self.pfsum[nr][self.c-1]
            if i > 0:
                top -= self.pfsum[i-1][self.c-1]
            if j > 0:
                top -= self.pfsum[nr][j-1]
            if i > 0 and j > 0:
                top += self.pfsum[i-1][j-1]
            if top > 0:
                total = (total + self.getWays(nr+1, j, k-1)) % MOD

        # Vertical cuts
        for nc in range(j, self.c-1):
            left = self.pfsum[self.r-1][nc]
            if i > 0:
                left -= self.pfsum[i-1][nc]
            if j > 0:
                left -= self.pfsum[self.r-1][j-1]
            if i > 0 and j > 0:
                left += self.pfsum[i-1][j-1]
            if left > 0:
                total = (total + self.getWays(i, nc+1, k-1)) % MOD

        return total % MOD

