from typing import List
from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # Each topping can be used at most twice.
        toppingCosts = toppingCosts * 2  # duplicate to allow two uses

        @cache
        def fn(i: int, x: int) -> int:
            """Return sum of a subsequence of toppings[i:] closest to x."""
            if i == len(toppingCosts) or x <= 0:
                return 0
            # Option 1: skip this topping.
            skip = fn(i + 1, x)
            # Option 2: take this topping (cost added) and reduce remaining target.
            take = toppingCosts[i] + fn(i + 1, x - toppingCosts[i])
            # Choose the option that gives a sum closest to x; tie‑break by smaller sum.
            return min(skip, take, key=lambda y: (abs(y - x), y))

        best = float('inf')
        for bc in baseCosts:
            total = bc + fn(0, target - bc)
            # Keep the result closest to target; tie‑break by smaller total.
            best = min(best, total, key=lambda t: (abs(t - target), t))
        return best

