from typing import List
from functools import lru_cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # each topping may be used twice
        toppingCosts = toppingCosts + toppingCosts

        @lru_cache(None)
        def dp(i: int, x: int) -> int:
            """Return the sum of a subsequence of toppingCosts[i:] closest to x."""
            if x <= 0 or i == len(toppingCosts):
                return 0
            # skip this topping
            skip = dp(i + 1, x)
            # take this topping
            take = toppingCosts[i] + dp(i + 1, x - toppingCosts[i])
            # choose the sum closer to x (tie → smaller sum)
            if abs(skip - x) < abs(take - x):
                return skip
            if abs(skip - x) > abs(take - x):
                return take
            return min(skip, take)

        best = float('inf')
        for bc in baseCosts:
            cur = bc + dp(0, target - bc)
            # keep the total cost nearer to target, tie → smaller total
            if abs(cur - target) < abs(best - target) or (abs(cur - target) == abs(best - target) and cur < best):
                best = cur
        return best

