class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        if Counter(s) != Counter(t):
            return False
        pos = defaultdict(deque)
        for idx, ch in enumerate(t):
            pos[ch].append(idx)
        a = [pos[ch].popleft() for ch in s]
        n = len(a)
        bit = BIT(n)
        last = defaultdict(lambda: -1)
        for i in range(n):
            prefix = bit.sum(a[i])
            cur_digit = int(s[i])
            for dig in range(cur_digit - 1, -1, -1):
                if last[dig] >= prefix:
                    return False
            bit.update(a[i], 1)
            last[cur_digit] = prefix
        return True

