from typing import List

class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)

        # basic validation of the matrix
        for i in range(n):
            if lcp[i][i] != n - i:
                return ''
            for j in range(i + 1, n):
                if lcp[i][j] != lcp[j][i]:
                    return ''
                max_len = n - max(i, j)
                if not (0 <= lcp[i][j] <= max_len):
                    return ''

        # union‑find for positions that must be equal
        parent = list(range(n))
        rank = [0] * n

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x: int, y: int) -> None:
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # unite all positions forced equal by the matrix
        for i in range(n):
            for j in range(i + 1, n):
                k = lcp[i][j]
                if k > 0:
                    for t in range(k):
                        union(i + t, j + t)

        # collect groups of equal positions
        groups = {}
        for i in range(n):
            r = find(i)
            groups.setdefault(r, []).append(i)

        # order groups by smallest index for greedy character assignment
        ordered_groups = sorted(groups.values(), key=lambda lst: min(lst))

        root_char = {}
        for group in ordered_groups:
            forbidden = set()
            for assigned_root, ch in root_char.items():
                # check if this group must differ from an already assigned group
                conflict = False
                for i in group:
                    for j in groups[assigned_root]:
                        if lcp[i][j] == 0:
                            conflict = True
                            break
                    if conflict:
                        break
                if conflict:
                    forbidden.add(ch)

            # pick the smallest available character
            for code in range(26):
                if code not in forbidden:
                    root_char[find(group[0])] = chr(ord('a') + code)
                    break
            else:
                return ''

        # construct the answer string
        s = ''.join(root_char[find(i)] for i in range(n))

        # verify that the constructed string matches the given LCP matrix
        dp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if s[i] == s[j]:
                    dp[i][j] = 1 + (dp[i + 1][j + 1] if i + 1 < n and j + 1 < n else 0)
                else:
                    dp[i][j] = 0

        for i in range(n):
            for j in range(n):
                if dp[i][j] != lcp[i][j]:
                    return ''

        return s

