from typing import List
from functools import lru_cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # Duplicate each topping to allow using each at most twice.
        toppingCosts = toppingCosts * 2
        n = len(toppingCosts)

        @lru_cache(None)
        def dfs(i: int, remaining: int) -> int:
            # Base: no toppings left or remaining ≤ 0.
            if i == n or remaining <= 0:
                return 0
            # Option 1: skip current topping.
            skip = dfs(i + 1, remaining)
            # Option 2: take current topping.
            take = toppingCosts[i] + dfs(i + 1, remaining - toppingCosts[i])
            # Return the sum whose value is closest to `remaining`.
            return min(skip, take, key=lambda s: (abs(s - remaining), s))

        best = float('inf')
        for bc in baseCosts:
            cur = bc + dfs(0, target - bc)
            best = min(best, cur, key=lambda c: (abs(c - target), c))
        return best

