from typing import List

class Solution:
    def findRestaurant(self, list1: List[str], list2: List[str]) -> List[str]:
        # Build a map of restaurant -> index for list2
        idx2 = {name: i for i, name in enumerate(list2)}
        candidates = []  # each element is [sum_of_indices, restaurant_name]

        # Find common restaurants and compute sum of indices
        for i, name in enumerate(list1):
            if name in idx2:
                candidates.append([i + idx2[name], name])

        # If no common restaurant, return empty list
        if not candidates:
            return []

        # Sort by the sum of indices (ascending)
        candidates.sort(key=lambda x: x[0])

        # Minimum sum is the first element after sorting
        min_sum = candidates[0][0]

        # Collect all restaurant names with this minimum sum
        result = [name for sum_val, name in candidates if sum_val == min_sum]
        return result

