from collections import defaultdict

class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        memo = defaultdict(int)

        def dfs(i: int, prev: int) -> int:
            if i == n:
                return 1
            key = (i, prev)
            if key in memo:
                return memo[key]
            total = 0
            if s[i] == 'I':
                # next rank must be greater than current
                for nxt in range(prev + 1, i + 2):
                    total += dfs(i + 1, nxt)
            else:  # 'D'
                # next rank can be <= current
                for nxt in range(prev + 1):
                    total += dfs(i + 1, nxt)
            memo[key] = total % MOD
            return memo[key]

        return dfs(0, 0) % MOD

