class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # Keep only characters that appear in s2
        s1 = ''.join(c for c in s1 if c in set(s2))
        if not set(s2).issubset(set(s1)):
            return 0

        s1_len = len(s1)
        index = 0          # current position in s1
        count = 0          # number of completed s2 blocks

        rec = {}           # maps position in s1 to (loop_index, count_of_s2)

        for i in range(n1):
            for c in s2:
                while True:
                    if index == s1_len:
                        index = 0
                        count += 1
                    if s1[index] == c:
                        index += 1
                        break
                    index += 1

            # After finishing one s1 block, check for cycle
            if index in rec:
                pre_loop, pre_count = rec[index]
                per_cycle = count - pre_count          # s2 repeats per cycle
                cycle_len = i - pre_loop               # length of the cycle (in s1 repetitions)
                remaining = n1 - pre_loop
                cycles = remaining // cycle_len
                count += per_cycle * cycles

                # Process remaining repetitions after full cycles
                for _ in range(remaining % cycle_len):
                    for c in s2:
                        while True:
                            if index == s1_len:
                                index = 0
                                count += 1
                            if s1[index] == c:
                                index += 1
                                break
                            index += 1
                break
            else:
                rec[index] = (i, count)

        return count // n2

