class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s) + 1
        memo = {}
        def dfs(i: int, rank: int) -> int:
            if i == len(s):
                return 1
            key = (i, rank)
            if key in memo:
                return memo[key]
            total = 0
            remaining = n - i
            if s[i] == 'D':
                for nxt in range(rank):
                    total = (total + dfs(i + 1, nxt)) % MOD
            else:  # 'I'
                for nxt in range(rank + 1, remaining):
                    total = (total + dfs(i + 1, nxt)) % MOD
            memo[key] = total
            return total
        ans = 0
        for rank in range(n):
            ans = (ans + dfs(0, rank)) % MOD
        return ans

