    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # If any character in s2 is not in s1, return 0
        if not set(s2).issubset(set(s1)):
            return 0

        s1_count = 0
        s2_count = 0
        index2 = 0
        record = {}   # key: index2, value: (s1_count, s2_count) at the beginning of the repetition

        while s1_count < n1:
            key = index2
            if key in record:
                s1_start, s2_start = record[key]
                cycle_s1 = s1_count - s1_start
                cycle_s2 = s2_count - s2_start
                cycles = (n1 - s1_count) // cycle_s1
                s2_count += cycles * cycle_s2
                s1_count += cycles * cycle_s1
                # Simulate the remaining repetitions without cycle detection
                for i in range(n1 - s1_count):
                    for char in s1:
                        if char == s2[index2]:
                            index2 += 1
                            if index2 == len(s2):
                                s2_count += 1
                                index2 = 0
                return s2_count // n2
            else:
                record[key] = (s1_count, s2_count)

            # Traverse one repetition of s1
            for char in s1:
                if char == s2[index2]:
                    index2 += 1
                    if index2 == len(s2):
                        s2_count += 1
                        index2 = 0

            s1_count += 1

        return s2_count // n2

