from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        m = len(pizza)
        n = len(pizza[0]) if m else 0

        # total apples count
        total_apples = sum(row.count('A') for row in pizza)
        if total_apples < k:
            return 0

        # prefix sum of apples: pref[i][j] = apples in rectangle (0,0)-(i-1,j-1)
        pref = [[0] * (n + 1) for _ in range(m + 1)]
        for i in range(m):
            row_sum = 0
            for j in range(n):
                row_sum += (pizza[i][j] == 'A')
                pref[i+1][j+1] = pref[i][j+1] + row_sum

        def hasApple(x1: int, y1: int, x2: int, y2: int) -> bool:
            # inclusive coordinates
            return (pref[x2+1][y2+1] - pref[x1][y2+1] - pref[x2+1][y1] + pref[x1][y1]) > 0

        @lru_cache(None)
        def dfs(i: int, j: int, cuts: int) -> int:
            # cuts = number of additional cuts we still need to make
            if cuts == 0:
                return 1 if hasApple(i, j, m-1, n-1) else 0
            ans = 0
            # horizontal cuts after row r
            for r in range(i, m-1):
                if hasApple(i, j, r, n-1):
                    ans += dfs(r+1, j, cuts-1)
            # vertical cuts after column c
            for c in range(j, n-1):
                if hasApple(i, j, m-1, c):
                    ans += dfs(i, c+1, cuts-1)
            return ans % 1000000007

        return dfs(0, 0, k-1) % 1000000007

