from typing import List
from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # Duplicate each topping to allow using it at most twice.
        toppingCosts = toppingCosts * 2

        @cache
        def fn(i: int, x: int) -> int:
            # Base case: no more toppings or the remaining target is non‑positive.
            if i == len(toppingCosts) or x <= 0:
                return 0
            # Option 1: skip this topping.
            skip = fn(i + 1, x)
            # Option 2: take this topping (one copy).
            take = toppingCosts[i] + fn(i + 1, x - toppingCosts[i])
            # Return the sum that brings us closest to x (prefer smaller sum on ties).
            return min(skip, take, key=lambda s: (abs(s - x), s))

        best = float('inf')
        for bc in baseCosts:
            # Desired topping sum to hit target.
            cur = bc + fn(0, target - bc)
            # Choose the overall result closest to target (prefer lower total on ties).
            if abs(cur - target) < abs(best - target) or (abs(cur - target) == abs(best - target) and cur < best):
                best = cur
        return best

