from typing import List
from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # Double each topping so it can be used 0, 1, or 2 times.
        toppings = toppingCosts * 2

        @cache
        def dfs(i: int, remain: int) -> int:
            # If we overshoot the target (remain < 0) or run out of toppings, no more cost.
            if remain < 0 or i == len(toppings):
                return 0

            # Option 1: skip this topping.
            skip = dfs(i + 1, remain)

            # Option 2: take this topping (use it once).
            take = toppings[i] + dfs(i + 1, remain - toppings[i])

            # Choose the result that is closest to `remain`.  Break ties by smaller total.
            if abs(take - remain) < abs(skip - remain):
                return take
            elif abs(take - remain) > abs(skip - remain):
                return skip
            else:
                return min(take, skip)

        best = float('inf')
        for bc in baseCosts:
            cur = bc + dfs(0, target - bc)
            # Pick the overall best cost: first by distance to target, then by smaller value.
            if (abs(cur - target) < abs(best - target) or
                (abs(cur - target) == abs(best - target) and cur < best)):
                best = cur
        return best

