class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # Quick check: every character in s2 must appear in s1
        if not set(s2).issubset(set(s1)):
            return 0
        s1_len, s2_len = len(s1), len(s2)
        i1 = i2 = 0  # pointers within s1 and s2
        cnt1 = cnt2 = 0  # completed blocks of s1 and s2
        rec = {}  # map s2 position -> (cnt1, cnt2) after a s1 block
        while cnt1 < n1:
            # Scan one copy of s1
            for ch in s1:
                if ch == s2[i2]:
                    i2 += 1
                    if i2 == s2_len:
                        cnt2 += 1
                        i2 = 0
            cnt1 += 1
            # Record state after finishing this s1 block
            if i2 not in rec:
                rec[i2] = (cnt1, cnt2)
            else:
                prev_cnt1, prev_cnt2 = rec[i2]
                cycle_len1 = cnt1 - prev_cnt1
                cycle_len2 = cnt2 - prev_cnt2
                remaining = n1 - cnt1
                if cycle_len1 > 0:
                    skip = remaining // cycle_len1
                    cnt1 += skip * cycle_len1
                    cnt2 += skip * cycle_len2
                break
        return cnt2 // n2

