from typing import List
from collections import defaultdict, deque

class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        # Build graph: ingredient -> list of recipes that need it
        graph = defaultdict(list)
        indegree = {recipe: 0 for recipe in recipes}
        for recipe, ing_list in zip(recipes, ingredients):
            for ing in ing_list:
                graph[ing].append(recipe)
                indegree[recipe] += 1

        # Initialize queue with supplies and any recipe that requires no ingredients
        queue = deque()
        in_queue = set()
        for item in supplies:
            queue.append(item)
            in_queue.add(item)

        result = []
        for recipe in recipes:
            if indegree[recipe] == 0:
                result.append(recipe)
                if recipe not in in_queue:
                    queue.append(recipe)
                    in_queue.add(recipe)

        # Process items in topological order
        while queue:
            cur = queue.popleft()
            for dependent in graph[cur]:
                indegree[dependent] -= 1
                if indegree[dependent] == 0:
                    result.append(dependent)
                    queue.append(dependent)
                    in_queue.add(dependent)

        # Return sorted list of possible recipes
        return sorted(result)

