class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        dp = [1]  # dp for length 1 (no constraints)
        for i, ch in enumerate(s):
            ndp = [0] * (i + 2)
            if ch == 'I':
                ndp[0] = 0
                acc = 0
                for j in range(1, i + 2):
                    acc = (acc + dp[j - 1]) % MOD
                    ndp[j] = acc
            else:  # 'D'
                ndp[i + 1] = 0
                acc = 0
                for j in range(i, -1, -1):
                    acc = (acc + dp[j]) % MOD
                    ndp[j] = acc
            dp = ndp
        return sum(dp) % MOD

