from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Edge case: no forbidden substrings
        if not forbidden:
            return len(word)
        # Maximum length of any forbidden word to limit search
        max_len = max(len(f) for f in forbidden)
        forb_set = set(forbidden)
        n = len(word)
        # bad[i] == True if a forbidden word ends at position i
        bad = [False] * n
        for i in range(n):
            # Check all substrings ending at i up to max_len
            for l in range(1, max_len + 1):
                start = i - l + 1
                if start < 0:
                    break
                if word[start:i+1] in forb_set:
                    bad[i] = True
                    break
        # Sliding window: left points to start of current valid substring
        left = 0
        ans = 0
        for i in range(n):
            if bad[i]:
                left = i + 1  # start fresh after the forbidden ends
            else:
                ans = max(ans, i - left + 1)
        return ans

