from functools import cache
import math
from typing import List

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # each topping can be used at most twice, duplicate the list
        toppings = toppingCosts * 2

        @cache
        def dfs(i: int, remain: int) -> int:
            # reached end of toppings list
            if i == len(toppings):
                return 0
            # option: skip this topping
            best = dfs(i + 1, remain)
            # option: take this topping once
            take = toppings[i] + dfs(i + 1, remain - toppings[i])
            # choose the sum closest to the remaining target
            return min(best, take, key=lambda s: (abs(s - remain), s))

        ans = math.inf
        for bc in baseCosts:
            need = target - bc
            best_sum = dfs(0, need)
            total = bc + best_sum
            ans = min(ans, total, key=lambda x: (abs(x - target), x))
        return int(ans)

