class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        if Counter(s) != Counter(t):
            return False

        # map each character in t to its positions
        pos = defaultdict(deque)
        for idx, ch in enumerate(t):
            pos[ch].append(idx)

        # construct target index sequence for s
        a = []
        for ch in s:
            a.append(pos[ch].popleft())

        n = len(a)
        bit = BIT(n + 1)

        # stores the minimal allowed index for each digit seen so far
        bound = defaultdict(lambda: -1)

        for i, ch in enumerate(s):
            inv = bit.sum(n) - bit.sum(a[i])
            bit.update(a[i], 1)

            digit = int(ch)
            for dig in range(digit - 1, -1, -1):
                if bound[dig] >= i - inv:
                    return False

            bound[digit] = i - inv

        return True

