from functools import lru_cache
from typing import List

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        rows, cols = len(pizza), len(pizza[0])
        MOD = 10**9 + 7

        # Prefix sum of apples: pre[i][j] = apples in rectangle (0,0)-(i-1,j-1)
        pre = [[0] * (cols + 1) for _ in range(rows + 1)]
        for i in range(rows):
            for j in range(cols):
                pre[i+1][j+1] = (pre[i+1][j] + pre[i][j+1] - pre[i][j] +
                                 (1 if pizza[i][j] == 'A' else 0))

        # Helper: does sub‑rectangle (i,j)-(rows‑1,cols‑1) contain at least one apple?
        def hasApple(i: int, j: int) -> bool:
            return pre[rows][cols] - pre[i][cols] - pre[rows][j] + pre[i][j] > 0

        @lru_cache(None)
        def dp(i: int, j: int, cuts: int) -> int:
            """Number of ways to cut sub‑pizza starting at (i,j) into (cuts+1) pieces."""
            if cuts == 0:                     # only one piece left
                return 1 if hasApple(i, j) else 0

            total = 0
            # Horizontal cuts
            for r in range(i, rows - 1):
                # rectangle (i, j) .. (r, cols-1) must have an apple
                if pre[r+1][cols] - pre[i][cols] - pre[r+1][j] + pre[i][j] > 0:
                    total += dp(r + 1, j, cuts - 1)
            # Vertical cuts
            for c in range(j, cols - 1):
                if pre[rows][c+1] - pre[i][c+1] - pre[rows][j] + pre[i][j] > 0:
                    total += dp(i, c + 1, cuts - 1)

            return total % MOD

        # Need k-1 cuts to obtain k pieces
        return dp(0, 0, k - 1) % MOD

