from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # duplicate each topping to allow using it at most twice
        toppingCosts = toppingCosts * 2

        @cache
        def fn(i: int, x: int) -> int:
            """Return sum of a subsequence of toppingCosts[i:] closest to x."""
            if x < 0 or i >= len(toppingCosts):
                return 0
            skip = fn(i + 1, x)
            take = toppingCosts[i] + fn(i + 1, x - toppingCosts[i])
            return min(skip, take, key=lambda y: (abs(y - x), y))

        best = float('inf')
        for bc in baseCosts:
            cur = bc + fn(0, target - bc)
            if abs(cur - target) < abs(best - target) or (abs(cur - target) == abs(best - target) and cur < best):
                best = cur
        return best

