from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie of all forbidden substrings
        trie = {}
        max_len = 0
        for f in forbidden:
            node = trie
            for ch in f:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node["end"] = True  # mark the end of a forbidden word
            max_len = max(max_len, len(f))

        left = 0          # left bound of the current window (inclusive)
        ans = 0           # longest valid substring length found so far
        n = len(word)
        for right in range(n):
            # Only need to check substrings of length up to max_len ending at right
            if max_len:
                node = trie
                # Walk backwards through the trie for up to max_len characters
                for k in range(right, max(right - max_len, -1), -1):
                    ch = word[k]
                    if ch not in node:
                        break
                    node = node[ch]
                    if "end" in node:
                        # substring word[k:right+1] is forbidden → move left bound past it
                        left = max(left, k + 1)
            # Update the answer with the current window size
            ans = max(ans, right - left + 1)
        return ans

