# Fixed code for counting permutations matching D/I sequence
class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s) + 1
        from collections import defaultdict
        mem = defaultdict(int)
        def dfs(i, val):
            # i: index of current element (0‑based), val: rank among i+1 numbers
            if i == 0:
                return 1 if val == 0 else 0
            if (i, val) in mem:
                return mem[(i, val)]
            total = 0
            if s[i-1] == 'I':
                # previous rank must be less than current rank
                for prev in range(val):
                    total += dfs(i-1, prev)
            else:  # 'D'
                # previous rank must be >= current rank
                for prev in range(val, i):
                    total += dfs(i-1, prev)
            mem[(i, val)] = total % MOD
            return mem[(i, val)]
        ans = 0
        for last in range(n):
            ans = (ans + dfs(n-1, last)) % MOD
        return ans

