class Solution:
    def findKthBit(self, N: int, K: int, R: bool = True) -> str:
        """Return the K-th bit of the N-th row in the binary string generation."""
        if K == 1:
            return '0' if R else '1'
        mid = 1 << (N - 1)  # length of left half
        if K == mid:
            return '1' if R else '0'
        if K < mid:
            return self.findKthBit(N - 1, K, R)
        # K is in the right half; map to mirrored position and flip.
        newK = 2 * mid - K + 1
        return self._invert(self.findKthBit(N - 1, newK, not R))

    def _invert(self, bit: str) -> str:
        """Invert a binary character."""
        return '0' if bit == '1' else '1'

