from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie for all forbidden strings
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node["end"] = True

        # Helper to check the prefix of s for any forbidden word.
        # Returns the length of the shortest forbidden prefix, or False if none.
        def isForbidden(s: str):
            node = trie
            cnt = 0
            for ch in s:
                if ch not in node:
                    return False
                node = node[ch]
                cnt += 1
                if "end" in node:
                    return cnt
            return False

        n = len(word)
        j = n  # exclusive bound of the longest valid substring starting at or after i
        ans = 0
        for i in range(n - 1, -1, -1):
            # Check the substring word[i:j] for a forbidden prefix
            found_len = isForbidden(word[i:j])
            if found_len:
                # Adjust the exclusive bound to exclude the forbidden word
                j = i + found_len - 1
            # Length of the current valid substring
            cur_len = j - i
            if cur_len > ans:
                ans = cur_len
        return ans

