class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # Edge cases
        if n1 == 0 or not s2:
            return 0
        if not set(s2).issubset(set(s1)):
            return 0

        cur = 0          # current index in s2
        cnt1 = 0         # number of processed s1 blocks
        cnt2 = 0         # number of completed s2 blocks

        visited = {}     # map from cur -> (cnt1, cnt2) at the start of a block

        while cnt1 < n1:
            if cur in visited:
                # Detect a cycle
                prev_cnt1, prev_cnt2 = visited[cur]
                cycle_len1 = cnt1 - prev_cnt1          # s1 blocks in cycle
                cycle_len2 = cnt2 - prev_cnt2          # s2 completions in cycle

                if cycle_len1 > 0:
                    # Skip whole cycles
                    remaining = n1 - cnt1
                    skip = remaining // cycle_len1
                    cnt1 += cycle_len1 * skip
                    cnt2 += cycle_len2 * skip
                # Stop further cycle detection for the leftover part
                visited.clear()
            else:
                visited[cur] = (cnt1, cnt2)

            # Process one copy of s1
            for ch in s1:
                if ch == s2[cur]:
                    cur += 1
                    if cur == len(s2):
                        cur = 0
                        cnt2 += 1

            cnt1 += 1

        return cnt2 // n2

