from collections import defaultdict
from typing import List

class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        if not pairs:
            return []
        graph = defaultdict(list)
        degree = defaultdict(int)
        for u, v in pairs:
            graph[u].append(v)
            degree[u] += 1
            degree[v] -= 1

        # Find start node: net out-degree == 1 (path start)
        start = None
        for node, deg in degree.items():
            if deg == 1:
                start = node
                break
        # If none, start from any vertex with outgoing edges (circuit case)
        if start is None:
            start = next(iter(graph))

        ans = []

        def dfs(u: int) -> None:
            while graph[u]:
                nxt = graph[u].pop()
                dfs(nxt)
            ans.append(u)

        dfs(start)
        ans.reverse()
        return [[ans[i], ans[i+1]] for i in range(len(ans)-1)]

