from functools import lru_cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # allow each topping to be used at most twice
        toppingCosts = toppingCosts * 2
        n = len(toppingCosts)

        @lru_cache(None)
        def dfs(i: int, remain: int) -> int:
            """Return topping sum from i onward closest to `remain`."""
            if i == n:
                return 0
            # skip current topping
            best = dfs(i + 1, remain)
            # take current topping if it does not exceed `remain`
            if toppingCosts[i] <= remain:
                take = toppingCosts[i] + dfs(i + 1, remain - toppingCosts[i])
                best = min(best, take, key=lambda s: (abs(s - remain), s))
            return best

        answer = None
        for base in baseCosts:
            total = base + dfs(0, target - base)
            if answer is None:
                answer = total
            else:
                diff = abs(total - target)
                ans_diff = abs(answer - target)
                if diff < ans_diff or (diff == ans_diff and total < answer):
                    answer = total
        return answer

