from typing import List

class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        window = []          # sorted list representing the current window
        ans = []             # store the medians
        for i, x in enumerate(nums):
            # Insert current element keeping window sorted
            insort(window, x)
            # Remove the element that slides out of the window
            if i >= k:
                to_remove = nums[i - k]
                idx = bisect_left(window, to_remove)
                del window[idx]
            # When we have a full window, compute the median
            if i >= k - 1:
                if k % 2 == 1:
                    ans.append(window[k // 2])
                else:
                    ans.append((window[k // 2 - 1] + window[k // 2]) / 2.0)
        return ans

