from typing import List

class Solution:
    def dp(self, i: int, prev: str, cnt: int, k: int, s: str, memo: dict) -> int:
        """Return minimal compressed length for suffix starting at i.
        prev = previous character kept in the current run,
        cnt = length of current run,
        k = remaining deletions allowed.
        """
        if k < 0:
            return float('inf')
        n = len(s)
        if i == n:
            # End of string – add the length of the final run
            if cnt == 0:
                return 0
            return 1 if cnt == 1 else 1 + len(str(cnt))

        key = (i, prev, cnt, k)
        if key in memo:
            return memo[key]

        # Option 1: delete s[i]
        del_opt = self.dp(i + 1, prev, cnt, k - 1, s, memo)

        # Option 2: keep s[i]
        if s[i] == prev:
            # Extend the current run
            keep_opt = self.dp(i + 1, prev, cnt + 1, k, s, memo)
        else:
            # Finish current run and start a new one
            cur_len = 0
            if cnt > 0:
                cur_len = 1 if cnt == 1 else 1 + len(str(cnt))
            keep_opt = cur_len + self.dp(i + 1, s[i], 1, k, s, memo)

        res = min(del_opt, keep_opt)
        memo[key] = res
        return res

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        """Compute the minimal possible length after deleting at most k chars."""
        return self.dp(0, "", 0, k, s, {})

