from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build reverse trie for forbidden strings
        root = {}
        for f in forbidden:
            node = root
            for ch in reversed(f):
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node["end"] = True

        n = len(word)
        max_len = max((len(f) for f in forbidden), default=0)
        left = 0
        ans = 0
        for right in range(n):
            node = root
            # walk backwards up to max_len characters
            for step in range(1, max_len + 1):
                idx = right - step + 1
                if idx < 0:
                    break
                ch = word[idx]
                if ch not in node:
                    break
                node = node[ch]
                if "end" in node:
                    # forbidden substring of length step ending at right
                    left = max(left, right - step + 2)
            ans = max(ans, right - left + 1)
        return ans

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # Early check: all characters of s2 must appear in s1
        if not set(s2).issubset(set(s1)):
            return 0
        # Mapping from index in s1 to (s1cnt, s2cnt) when this index is seen
        recall = {}
        s1cnt = 0      # number of full s1 blocks consumed
        s2cnt = 0      # number of full s2 blocks completed
        index = 0      # current position within s1 for the next character search

        while s1cnt < n1:
            for ch in s2:
                # Move index until we find the required character
                while index < len(s1) and s1[index] != ch:
                    index += 1
                if index == len(s1):
                    # Need a new s1 block
                    s1cnt += 1
                    index = 0
                    if s1cnt == n1:
                        return s2cnt // n2
                    # Search again in the fresh block
                    while index < len(s1) and s1[index] != ch:
                        index += 1
                index += 1
            # Finished one full s2
            s2cnt += 1
            # If we ended exactly at the end of s1, count that block
            if index == len(s1):
                s1cnt += 1
                index = 0
                if s1cnt == n1:
                    return s2cnt // n2
            # Cycle detection
            if index in recall:
                pre_s1cnt, pre_s2cnt = recall[index]
                # Lengths of one cycle
                cycle_s1 = s1cnt - pre_s1cnt
                cycle_s2 = s2cnt - pre_s2cnt
                # Skip whole cycles
                remaining = n1 - pre_s1cnt
                full = remaining // cycle_s1
                s2cnt += full * cycle_s2
                s1cnt += full * cycle_s1
                # Simulate the remainder of s1 blocks
                while s1cnt < n1:
                    for ch in s2:
                        while index < len(s1) and s1[index] != ch:
                            index += 1
                        if index == len(s1):
                            s1cnt += 1
                            index = 0
                            if s1cnt == n1:
                                break
                            while index < len(s1) and s1[index] != ch:
                                index += 1
                        index += 1
                    else:
                        s2cnt += 1
                return s2cnt // n2
            else:
                recall[index] = (s1cnt, s2cnt)
        return s2cnt // n2

