class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        graph = defaultdict(list)
        degree = defaultdict(int)  # net out-degree for each node
        for u, v in pairs:
            graph[u].append(v)
            degree[u] += 1
            degree[v] -= 1

        # Find start node (net out-degree == 1), otherwise any existing node
        start = None
        for k, d in degree.items():
            if d == 1:
                start = k
                break
        if start is None:
            start = next(iter(graph)) if graph else None

        ans = []

        def dfs(u: int) -> None:
            while graph[u]:
                v = graph[u].pop()
                dfs(v)
            ans.append(u)

        if start is not None:
            dfs(start)

        ans.reverse()
        # Convert the Eulerian path to a list of consecutive pairs
        return [[ans[i], ans[i+1]] for i in range(len(ans)-1)]

