from collections import defaultdict

class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        memo = defaultdict(int)

        def dfs(i: int, val: int) -> int:
            if i == n:
                return 1
            key = (i, val)
            if key in memo:
                return memo[key]
            total = 0
            if s[i] == 'D':
                # next value must be smaller
                for nxt in range(0, val):
                    total = (total + dfs(i+1, nxt)) % MOD
            else:  # 'I'
                # next value must be >= current
                for nxt in range(val, n - i):
                    total = (total + dfs(i+1, nxt)) % MOD
            memo[key] = total
            return total

        ans = 0
        for first in range(n+1):
            ans = (ans + dfs(0, first)) % MOD
        return ans

