from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie for all forbidden substrings
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node["end"] = True

        def isForbidden(s: str) -> int:
            """
            Returns the length of the shortest forbidden prefix of s.
            If there is no forbidden prefix, returns -1.
            """
            node = trie
            length = 0
            for ch in s:
                if ch not in node:
                    return -1
                node = node[ch]
                length += 1
                if "end" in node:
                    return length
            return -1

        n = len(word)
        right = n  # exclusive bound of the current valid window
        best = 0
        for left in range(n - 1, -1, -1):
            # If adding word[left] creates a forbidden substring starting at left,
            # shrink the window so that it ends just after that substring.
            prefix_len = isForbidden(word[left:right])
            if prefix_len != -1:
                right = left + prefix_len
            best = max(best, right - left)
        return best

