class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if n1 == 0:
            return 0
        if set(s2) - set(s1):
            return 0

        # Precompute for one block of s1: count of s2 matched and next state in s2
        # State: index in s2 -> (s1_count, s2_count)
        state = {}
        s1_count = 0
        s2_count = 0
        index = 0

        while s1_count < n1:
            if index in state:
                pre_s1_count, pre_s2_count = state[index]
                cycle_s1_count = s1_count - pre_s1_count
                cycle_s2_count = s2_count - pre_s2_count
                if cycle_s1_count == 0:
                    return 0
                remaining = n1 - s1_count
                cycles = remaining // cycle_s1_count
                s1_count += cycles * cycle_s1_count
                s2_count += cycles * cycle_s2_count
                if s1_count >= n1:
                    break
            else:
                state[index] = (s1_count, s2_count)

            count2 = 0
            for char in s1:
                if char == s2[index]:
                    index += 1
                    if index == len(s2):
                        count2 += 1
                        index = 0
            s1_count += 1
            s2_count += count2

        return s2_count // n2

