class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        if n == 0:
            return ''
        # basic validation
        for i in range(n):
            for j in range(i + 1, n):
                if lcp[i][j] != lcp[j][i]:
                    return ''
                if lcp[i][j] > n - j:
                    return ''
        for i in range(n):
            if lcp[i][i] != n - i:
                return ''
        # build groups
        pattern = [None] * n
        next_id = 0
        for i in range(n):
            if pattern[i] is not None:
                continue
            pattern[i] = next_id
            next_id += 1
            for j in range(i + 1, n):
                if lcp[i][j] > 0:
                    if pattern[j] is not None and pattern[j] != pattern[i]:
                        return ''
                    pattern[j] = pattern[i]
        # compute lcp from pattern
        pattern_lcp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if pattern[i] == pattern[j]:
                    if i + 1 < n and j + 1 < n:
                        pattern_lcp[i][j] = pattern_lcp[i + 1][j + 1] + 1
                    else:
                        pattern_lcp[i][j] = 1
                else:
                    pattern_lcp[i][j] = 0
        for i in range(n):
