from typing import List
from functools import lru_cache
import math

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # each topping can be used at most twice → duplicate the list
        toppingCosts = toppingCosts * 2

        @lru_cache(None)
        def dfs(i: int, need: int) -> int:
            # base case: no more toppings or need is non‑positive
            if need <= 0 or i == len(toppingCosts):
                return 0
            # option 1: skip this topping
            skip = dfs(i + 1, need)
            # option 2: take this topping once
            take = toppingCosts[i] + dfs(i + 1, need - toppingCosts[i])
            # choose the result closest to `need` (break ties with smaller sum)
            return min(skip, take, key=lambda v: (abs(v - need), v))

        best = math.inf
        for bc in baseCosts:
            need = target - bc
            cost = bc + dfs(0, need)
            # keep the combination that is nearest to target, preferring lower total cost on ties
            if best == math.inf or (abs(cost - target), cost) < (abs(best - target), best):
                best = cost
        return int(best)

