class Solution:
    def dp(self, i, s, prev, k, ct, n, memo):
        if k < 0:
            return float('inf')
        if i >= n:
            if ct > 1:
                return 1 + len(str(ct))
            elif ct == 1:
                return 1
            else:
                return 0
        key = (i, prev, ct, k)
        if key in memo:
            return memo[key]

        # keep s[i]
        if s[i] == prev:
            inc = self.dp(i+1, s, prev, k, ct+1, n, memo)
        else:
            # cost of previous group
            cost_prev = 0
            if ct > 1:
                cost_prev = 1 + len(str(ct))
            elif ct == 1:
                cost_prev = 1
            inc = cost_prev + self.dp(i+1, s, s[i], k, 1, n, memo)

        # delete s[i]
        exc = self.dp(i+1, s, prev, k-1, ct, n, memo)

        ans = min(inc, exc)
        memo[key] = ans
        return ans

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        return self.dp(0, s, "", k, 0, n, {})

