class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        n = len(word)
        if not forbidden:
            return n

        # Build Aho-Corasick automaton
        nodes = [{'children': {}, 'fail': 0, 'min_len': float('inf'), 'explicit_min_len': float('inf')}]
        for f in forbidden:
            node = 0
            for c in f:
                if c not in nodes[node]['children']:
                    nodes[node]['children'][c] = len(nodes)
                    nodes.append({'children': {}, 'fail': 0, 'min_len': float('inf'), 'explicit_min_len': float('inf')})
                node = nodes[node]['children'][c]
            nodes[node]['explicit_min_len'] = min(nodes[node]['explicit_min_len'], len(f))

        from collections import deque
        q = deque()
        for c, child in nodes[0]['children'].items():
            nodes[child]['fail'] = 0
            q.append(child)

        while q:
            r = q.popleft()
            fail = nodes[r]['fail']
            nodes[r]['min_len'] = min(nodes[r]['explicit_min_len'], nodes[fail]['min_len'])
            for c, child in nodes[r]['children'].items():
                f = nodes[r]['fail']
                while f != 0 and c not in nodes[f]['children']:
                    f = nodes[f]['fail']
                if c in nodes[f]['children']:
                    nodes[child]['fail'] = nodes[f]['children'][c]
                else:
                    nodes[child]['fail'] = 0
                q.append(child)

        nodes[0]['min_len'] = nodes[0]['explicit_min_len']

        # Precompute max_start for each index in the word
        max_start = [-1] * n
        node = 0
        for i in range(n):
            c = word[i]
            while node != 0 and c not in nodes[node]['children']:
                node = nodes[node]['fail']
            if c in nodes[node]['children']:
                node = nodes[node]['children'][c]
            else:
                node = 0
            min_len_i = nodes[node]['min_len']
            if min_len_i < float('inf'):
                max_start[i] = i - min_len_i + 1
            else:
                max_start[i] = -1

        # Two-pointer scan
        left = 0
        max_valid = 0
        for right in range(n):
            if max_start[right] >= left:
                left = max_start[right] + 1
            current_len = right - left + 1
            if current_len > max_valid:
                max_valid = current_len
        return max_valid

