class Solution:
    def smallestString(self, s: str) -> str:
        # If the string consists only of 'a', replace the last character with 'z'
        if set(s) == {'a'}:
            return s[:-1] + 'z'
        n = len(s)
        # Find the first non-'a' character after leading 'a's
        i = 0
        while i < n and s[i] == 'a':
            i += 1
        # Decrement characters until an 'a' is encountered
        ans = list(s)
        while i < n and ans[i] != 'a':
            ans[i] = chr(ord(ans[i]) - 1)
            i += 1
        return ''.join(ans)

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if not set(s2).issubset(set(s1)):
            return 0
        # Keep only characters that could possibly match s2
        s1 = ''.join(ch for ch in s1 if ch in set(s2))
        if not s1:
            return 0

        index = {}          # map from position in s2 to (cnt1, cnt2)
        cnt1 = cnt2 = 0    # number of processed s1 blocks and completed s2 blocks
        j = 0              # pointer inside s2

        while cnt1 < n1:
            # Process one block of s1
            for ch in s1:
                if ch == s2[j]:
                    j += 1
                    if j == len(s2):
                        cnt2 += 1
                        j = 0
            cnt1 += 1

            # Detect a cycle by the position in s2 after a block
            if j in index:
                pre_cnt1, pre_cnt2 = index[j]
                cycle_cnt1 = cnt1 - pre_cnt1
                cycle_cnt2 = cnt2 - pre_cnt2
                break
            else:
                index[j] = (cnt1, cnt2)

        # If we finished all blocks without a cycle, answer is straightforward
        if cnt1 == n1:
            return cnt2 // n2

        # Compute repetitions using the discovered cycle
        pre_cnt1, pre_cnt2 = index[j]
        cycle_cnt1 = cnt1 - pre_cnt1
        cycle_cnt2 = cnt2 - pre_cnt2
        remaining = n1 - pre_cnt1
        # Number of full cycles we can apply
        full_cycles = remaining // cycle_cnt1
        cnt2 = pre_cnt2 + full_cycles * cycle_cnt2
        # Process the remaining blocks (less than one full cycle)
        rest_blocks = remaining % cycle_cnt1
        for _ in range(rest_blocks):
            for ch in s1:
                if ch == s2[j]:
                    j += 1
                    if j == len(s2):
                        cnt2 += 1
                        j = 0

        return cnt2 // n2
